<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Tip Calculator Online','description'=>'Calculate tip amount and total bill instantly.','url'=>'https://smarttoolz.in/tools/tip-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">TIP CALCULATOR</span><h1>Tip Calculator</h1><p>Calculate tip and split the total between people.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Bill amount<input id="bill" type="number" min="0" step="0.01" placeholder="1000"></label><label>Tip percentage<input id="tip" type="number" min="0" step="0.5" value="10"></label><label>People<input id="people" type="number" min="1" step="1" value="1"></label><button id="go" class="tool-btn">Calculate Tip</button><p id="out" style="margin-top:15px;font-size:18px;font-weight:800"></p></div></section></main><script>(()=>{const $=id=>document.getElementById(id),o=$('out');$('go').onclick=()=>{let b=+$('bill').value,t=+$('tip').value,p=+$('people').value;if(!Number.isFinite(b)||!Number.isFinite(t)||!Number.isFinite(p)||b<0||t<0||p<1){o.textContent='Enter valid values.';return}let x=b*t/100,total=b+x;o.textContent=`Tip: ${x.toFixed(2)} · Total: ${total.toFixed(2)} · Per person: ${(total/p).toFixed(2)}`}})();</script><?php smarttoolz_tool_page_end(); ?>